package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching products by category and price range
func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortCol := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category is required", http.StatusBadRequest)
		return
	}

	// Validate sort column against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "created_at": true}
	if sortCol == "" {
		sortCol = "name"
	}
	if !allowedSorts[sortCol] {
		sortCol = "name"
	}

	// Build query with parameterized category but inline price filters
	// Price values are expected to be numeric strings from the frontend slider
	var conditions []string
	conditions = append(conditions, "category = $1")

	if minPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price >= %s", minPrice))
	}
	if maxPrice != "" {
		conditions = append(conditions, fmt.Sprintf("price <= %s", maxPrice))
	}

	query := fmt.Sprintf(
		"SELECT id, name, price, description FROM products WHERE %s ORDER BY %s LIMIT 50",
		strings.Join(conditions, " AND "),
		sortCol,
	)

	rows, err := db.Query(query, category)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("["))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(","))
		}
		first = false
		// Manual JSON construction for performance
		jsonLine := fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`,
			id, strings.ReplaceAll(name, `"`, `\"`), price, strings.ReplaceAll(description, `"`, `\"`))
		w.Write([]byte(jsonLine))
	}
	w.Write([]byte("]"))
}

// healthHandler for load balancer checks
func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
